Jobs:
query Jobs($departmentIds: [Int]
  $officeIds: [Int]
  $languages: [String]
  $roleTypes: [String]
  $searchQuery: String
) {
  jobs(departmentIds: $departmentIds
    officeIds: $officeIds
    languages: $languages
    roleTypes: $roleTypes
    searchQuery: $searchQuery
  ) {
    id
    title
    department {
      name
      id
    }
    office {
      id,
      location
    }
    location {
      name
    }
  }
}

Job:
query Job($id: ID!) {
  job(id: $id) {
    title
    id
    content
    department {
      id
      name
    }
    office {
      location
      id
    }
    questions {
      label
      description
      required
      fields {
        name
        type
        values {
          value
          label
        }
      }
    }
    location_questions {
      label
      required
      fields {
        name
        type
      }
    }
  }
}
